  1	/**
  2	 * Batch command parsing, validation, execution, and error reporting.
  3	 *
  4	 * Parses JSON batch input from stdin/file/inline, validates command paths
  5	 * against the CLI's introspection tree, executes in atomic or immediate
  6	 * mode, and produces helpful error messages.
  7	 */
  8	
  9	import * as fs from "node:fs/promises";
 10	import * as path from "node:path";
 11	import chalk from "chalk";
 12	import type { Command, CommanderError } from "commander";
 13	import { ZodError } from "zod";
 14	import {
 15	  BatchInputSchema,
 16	  type BatchCommand,
 17	  type BatchCommandResult,
 18	  type BatchExecMode,
 19	  type BatchExecResult,
 20	  type BatchInput,
 21	} from "../schema/batch.js";
 22	import { initContext } from "../parser/yaml.js";
 23	import { shadowAutoCommit, shadowPushAsync } from "../parser/shadow.js";
 24	import type { CommandMeta } from "./introspection.js";
 25	import { extractCommandTree, findCommand, flattenCommandTree } from "./introspection.js";
 26	import { findClosestCommand } from "./suggest.js";
 27	import { createBatchCommandFilter } from "./command-annotations.js";
 28	import { setJsonMode, setVerboseMode } from "./output.js";
 29	import {
 30	  BatchExitError,
 31	  OutputCapture,
 32	  installExitInterceptor,
 33	  uninstallExitInterceptor,
 34	  setBatchMode,
 35	  isBatchMode,
 36	} from "./batch-context.js";
 37	import {
 38	  activateBatchBuffer,
 39	  deactivateBatchBuffer,
 40	} from "./batch-write-buffer.js";
 41	
 42	// ── Input Source Types ───────────────────────────────────────────────
 43	
 44	export type BatchInputSource =
 45	  | { type: "stdin" }
 46	  | { type: "file"; path: string }
 47	  | { type: "inline"; json: string };
 48	
 49	const BATCH_STDIN_IDLE_TIMEOUT_MS = 1000;
 50	
 51	// ── Error Types ─────────────────────────────────────────────────────
 52	
 53	export class BatchParseError extends Error {
 54	  constructor(message: string) {
 55	    super(message);
 56	    this.name = "BatchParseError";
 57	  }
 58	}
 59	
 60	export type BatchValidationErrorType =
 61	  | "unknown_command"
 62	  | "missing_required"
 63	  | "unknown_arg"
 64	  | "rejected_command";
 65	
 66	export interface BatchValidationError {
 67	  /** Index in the batch array */
 68	  index: number;
 69	  /** Correlation ID if provided */
 70	  id?: string;
 71	  /** The command string from input */
 72	  command: string;
 73	  /** Error classification */
 74	  type: BatchValidationErrorType;
 75	  /** Human-readable error message */
 76	  message: string;
 77	  /** Suggested correction (e.g. closest command name) */
 78	  suggestion?: string;
 79	}
 80	
 81	export interface BatchValidationResult {
 82	  /** Whether all commands passed validation */
 83	  valid: boolean;
 84	  /** Validated commands (only present when valid) */
 85	  commands: BatchCommand[];
 86	  /** Validation errors */
 87	  errors: BatchValidationError[];
 88	}
 89	
 90	export interface ValidateBatchOptions {
 91	  /**
 92	   * Optional predicate to filter which commands are allowed.
 93	   * Extension point for allowed-commands task (@01KGR05NE).
 94	   * When provided, commands that don't pass the filter are rejected
 95	   * with a "rejected_command" error.
 96	   */
 97	  commandFilter?: (cmd: CommandMeta) => boolean;
 98	}
 99	
100	// ── Parsing ─────────────────────────────────────────────────────────
101	
102	/**
103	 * Read stdin with an idle timeout so non-interactive callers that keep
104	 * stdin open without writing do not block forever.
105	 */
106	async function readStdinWithIdleTimeout(timeoutMs: number): Promise<string> {
107	  return new Promise((resolve) => {
108	    let data = "";
109	    let timeout: ReturnType<typeof setTimeout> | undefined;
110	
111	    const cleanup = () => {
112	      if (timeout) {
113	        clearTimeout(timeout);
114	      }
115	      process.stdin.removeListener("data", onData);
116	      process.stdin.removeListener("end", onEnd);
117	      process.stdin.removeListener("error", onError);
118	    };
119	
120	    const armTimeout = () => {
121	      if (timeout) {
122	        clearTimeout(timeout);
123	      }
124	      timeout = setTimeout(() => {
125	        cleanup();
126	        resolve(data);
127	      }, timeoutMs);
128	      timeout.unref?.();
129	    };
130	
131	    const onData = (chunk: string) => {
132	      data += chunk;
133	      armTimeout();
134	    };
135	
136	    const onEnd = () => {
137	      cleanup();
138	      resolve(data);
139	    };
140	
141	    const onError = () => {
142	      cleanup();
143	      resolve(data);
144	    };
145	
146	    process.stdin.setEncoding("utf8");
147	    process.stdin.on("data", onData);
148	    process.stdin.on("end", onEnd);
149	    process.stdin.on("error", onError);
150	    process.stdin.resume();
151	    armTimeout();
152	  });
153	}
154	
155	/**
156	 * Read raw text from a batch input source.
157	 */
158	async function readSource(source: BatchInputSource): Promise<string> {
159	  switch (source.type) {
160	    case "inline":
161	      return source.json;
162	
163	    case "file":
164	      try {
165	        return await fs.readFile(source.path, "utf-8");
166	      } catch (err) {
167	        throw new BatchParseError(
168	          `Failed to read batch file: ${(err as Error).message}`,
169	        );
170	      }
171	
172	    case "stdin": {
173	      const text = process.stdin.isTTY
174	        ? await (async () => {
175	            const chunks: Buffer[] = [];
176	            for await (const chunk of process.stdin) {
177	              chunks.push(chunk as Buffer);
178	            }
179	            return Buffer.concat(chunks).toString("utf-8");
180	          })()
181	        : await readStdinWithIdleTimeout(BATCH_STDIN_IDLE_TIMEOUT_MS);
182	
183	      if (!text.trim()) {
184	        throw new BatchParseError(
185	          `No input received on stdin. Provide --commands <json>, --file <path>, or pipe JSON via stdin.`,
186	        );
187	      }
188	      return text;
189	    }
190	  }
191	}
192	
193	/**
194	 * Parse batch input from a source, returning validated commands.
195	 *
196	 * @throws {BatchParseError} on invalid JSON, empty array, or schema violations
197	 */
198	export async function parseBatchInput(
199	  source: BatchInputSource,
200	): Promise<BatchInput> {
201	  const raw = await readSource(source);
202	
203	  // Parse JSON — preserve the native error message which includes position
204	  let parsed: unknown;
205	  try {
206	    parsed = JSON.parse(raw);
207	  } catch (err) {
208	    throw new BatchParseError(
209	      `Invalid JSON: ${(err as SyntaxError).message}`,
210	    );
211	  }
212	
213	  // Validate against schema
214	  try {
215	    return BatchInputSchema.parse(parsed);
216	  } catch (err) {
217	    if (err instanceof ZodError) {
218	      const messages = err.errors.map((e) => {
219	        const path = e.path.length > 0 ? ` at ${e.path.join(".")}` : "";
220	        return `${e.message}${path}`;
221	      });
222	      throw new BatchParseError(
223	        `Batch validation failed: ${messages.join("; ")}`,
224	      );
225	    }
226	    throw err;
227	  }
228	}
229	
230	// ── Validation ──────────────────────────────────────────────────────
231	
232	/**
233	 * Extract the option name from Commander flag syntax.
234	 * e.g. "-f, --force" → "force", "--spec-ref <value>" → "spec-ref"
235	 */
236	function extractOptionName(flags: string): string | null {
237	  const match = flags.match(/--([a-zA-Z0-9-]+)/);
238	  return match ? match[1] : null;
239	}
